mapper.select:
select , pr.proj_name
from cbs.t_project_prep p left join cbs.t_project pr on pr.project_id = p.project_id
where p.prep_id = #{id}

mapper.update:
update cbs.t_project_prep
project_id = #{p.project_id}, prep_date = #{p.prep_date}, content = #{p.content}, status = #{p.status}, checker = #{p.checker}, remark = #{p.remark},
where prep_id = #{p.prep_id}
